    result_id: failedSrc.result_id || src.result_id, file_path: failedSrc.file_path || src.file_path,
    file_id: failedSrc.file_id || src.file_id, file_name: failedSrc.file_name || src.file_name,
    locale: failedSrc.locale || src.locale, control_code: failedSrc.control_code || src.control_code,
    control_title: failedSrc.control_title || src.control_title, control_requirement: failedSrc.control_requirement || src.control_requirement,
    warnings: (failedSrc.warnings || []).concat('page_ocr_request_failed'),
  }};
});

// Gabungkan hasil transkripsi semua halaman (urut nomor halaman) jadi satu
// dokumen, lalu terapkan ambang "cukup teks" yang sama seperti jalur gambar biasa
// (strip placeholder [tidak terbaca]/[illegible] dulu sebelum hitung panjang).
const MIN_TEXT = 50;
const items = $input.all();
const src = $('Fan-out & Detect').first().json;

const pages = items.map(it => it.json).sort((a, b) => (a.page_number || 0) - (b.page_number || 0));
const anyOk = pages.some(p => p.page_ok);

const combinedText = pages
  .map(p => '--- Halaman ' + p.page_number + ' ---\n' + (p.page_text || ''))
  .join('\n\n')
  .trim();

const meaningfulText = combinedText
  .replace(/\[(tidak terbaca|illegible|Halaman \d+: gagal dibaca)\]/gi, '')
  .replace(/--- Halaman \d+ ---/g, '')
  .replace(/[^\p{L}\p{N}]/gu, '');

const hasEnoughText = anyOk && meaningfulText.length >= MIN_TEXT;

return [{ json: {
  file_id: src.file_id, file_name: src.file_name,
  file_category: 'PDF',
  content_mode: hasEnoughText ? 'text' : 'none',
  extraction_method: 'scanned_pdf_ocr',
  text: hasEnoughText ? combinedText : '',
  visual_description: '',
  page_count: pages.length,
  status: hasEnoughText ? undefined : 'unreadable',
  error_reason: hasEnoughText ? null : 'scanned_pdf_no_readable_text',
  result_id: src.result_id || null, file_path: src.file_path || null, locale: src.locale || 'en',
  control_code: src.control_code || '', control_title: src.control_title || '', control_requirement: src.control_requirement || '',
  warnings: src.warnings || [],
}}];

// 'Extract PDF Text' membuang binary PDF asli, cuma menyisakan metadata
// (numpages, info, text). Ambil kembali binary-nya dari 'Fan-out & Detect' —
// titik terakhir sebelum binary itu hilang — supaya 'Rasterize via HTTP' punya
// field binary 'data' untuk dikirim.
const items = $input.all();
return items.map((item, i) => {
  const srcBinary = $('Fan-out & Detect').itemMatching(i).binary;
  return { json: item.json, binary: srcBinary };
});
